/* =====================================================================================================
   MANUAL SQL UPGRADE SCRIPT
   Migration: 202608200600001_AddCopilotInteractionHistory

   Creates the tables behind the optional Copilot AI interaction-history import (Microsoft Graph
   getAllEnterpriseInteractions). For customers/DBAs who upgrade the database by hand instead of
   running the installer.

   WHAT THIS DOES
     * Creates 10 new, empty tables (interactions, sessions, five lookups, a key-phrase link table,
       a per-user watermark table and a per-run import log).
     * Creates their supporting indexes.
     * Stamps dbo.__MigrationHistory so the installer, DatabaseUpgrader and the web-app Health page
       all treat the migration as applied.

   IMPACT
     * Purely additive: no existing table is altered, so there is no table rewrite, no blocking
       schema lock and no downtime. It completes in seconds on a database of any size.
     * No prompt or response text is ever stored in these tables. The importer converts each Copilot
       interaction body into counts (length, word count, attachment/link/mention counts) and discards
       it. The only free text stored is Azure AI Language key phrases, and only when cognitive
       services are enabled.

   NOTES
     * Idempotent - safe to re-run. Every object is created only if it is missing, and the history
       stamp is reached even when there was nothing left to create.
     * Prerequisite: 202608191533567_DeprecateTeamsAddons
     * Run against the Analytics database.
   ===================================================================================================== */
SET NOCOUNT ON;

DECLARE @migration nvarchar(100) = N'202608200600001_AddCopilotInteractionHistory';
DECLARE @predecessor nvarchar(100) = N'202608191533567_DeprecateTeamsAddons';
DECLARE @start datetime2(3) = SYSUTCDATETIME();
DECLARE @msg nvarchar(2000);

IF OBJECT_ID(N'dbo.__MigrationHistory', 'U') IS NULL
BEGIN
    RAISERROR('AddCopilotInteractionHistory: dbo.__MigrationHistory does not exist - this does not look like an Analytics database. Nothing was changed.', 16, 1);
    RETURN;
END

IF NOT EXISTS (SELECT 1 FROM dbo.__MigrationHistory WHERE MigrationId = @predecessor)
BEGIN
    SET @msg = N'AddCopilotInteractionHistory: prerequisite migration ' + @predecessor
        + N' has not been applied. Apply earlier migrations first. Nothing was changed.';
    RAISERROR(@msg, 16, 1);
    RETURN;
END

