/* ---------------------------------------------------------------------------------------------------
   Record the migration so EF (DatabaseUpgrader / MigrateDatabaseToLatestVersion) and the web-app
   Health page treat it as applied.

   Unlike the raw-SQL index migrations in this folder, this one changes the EF model, so its snapshot
   is NOT identical to its predecessor's and cannot be copied from the previous row. The Model value
   below is the migration's own snapshot, taken byte-for-byte from the generated migration script.
   --------------------------------------------------------------------------------------------------- */
DECLARE @migrationId nvarchar(150) = N'202608200600001_AddCopilotInteractionHistory';

IF NOT EXISTS (SELECT 1 FROM dbo.__MigrationHistory WHERE MigrationId = @migrationId)
BEGIN
    INSERT [dbo].[__MigrationHistory]([MigrationId], [ContextKey], [Model], [ProductVersion])
    VALUES (@migrationId, N'Common.Entities.Migrations.Configuration', , N'6.5.2');
    RAISERROR('AddCopilotInteractionHistory: recorded in __MigrationHistory.', 0, 1) WITH NOWAIT;
END
ELSE
    RAISERROR('AddCopilotInteractionHistory: already recorded in __MigrationHistory, nothing to do.', 0, 1) WITH NOWAIT;

SET @msg = N'AddCopilotInteractionHistory: finished in '
    + CAST(DATEDIFF(MILLISECOND, @start, SYSUTCDATETIME()) AS nvarchar(20)) + N'ms.';
RAISERROR(@msg, 0, 1) WITH NOWAIT;

